import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int count_input = scanner.nextInt();
        int[] prefix_sum = new int[5001];
        for (int i = 0; i < count_input; i++) {
            int val = scanner.nextInt();
            prefix_sum[val]++;
        }
        int window = scanner.nextInt();
        for (int i = 1; i <= 3000; i++) {
            prefix_sum[i] += prefix_sum[i - 1];
        }
        int max_count = 0;
        for (int start_idx = 1; start_idx + window <= 5000; start_idx++) {
            int current_count = prefix_sum[start_idx + window] - prefix_sum[start_idx - 1];
            if (current_count > max_count) {
                max_count = current_count;
            }
        }
        System.out.println(max_count);
        scanner.close();
    }
}
